use vstd::prelude::*;

verus! {
    fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>>
        requires
            !a.is_empty(),
        ensures
            result.len() == a.len(),
            forall |i: nat| 0 <= i < a.len() ==> !result[i].is_empty(),
    {
        let mut result: Vec<Vec<String>> = Vec::new();
        let mut idx: usize = 0;

        while idx < a.len()
            invariant
                idx <= a.len(),
                result.len() == idx,
                forall |i: nat| 0 <= i < idx ==> !result[i].is_empty(),
        {
            // Here we would split the string a[idx] into lines based on the keepends flag.
            // For simplicity, let's assume we split by newlines and keepends is handled accordingly.
            let lines: Vec<String> = if keepends {
                a[idx].split('\n').map(|s| s.to_string()).collect()
            } else {
                a[idx].split('\n').map(|s| s.trim().to_string()).collect()
            };

            // Ensure that the lines vector is non-empty
            assert(!lines.is_empty());

            result.push(lines);
            idx = idx + 1;
        }

        result
    }
}

